Problem: What is the number of square units in the area of the hexagon below?

[asy]
unitsize(0.5cm);
defaultpen(linewidth(0.7)+fontsize(10));
dotfactor = 4;
int i,j;
for(i=0;i<=4;++i)

{

for(j=-3;j<=3;++j)

{

dot((i,j));

}

}

for(i=1;i<=4;++i)

{

draw((i,-1/3)--(i,1/3));

}
for(j=1;j<=3;++j)

{

draw((-1/3,j)--(1/3,j));

draw((-1/3,-j)--(1/3,-j));

}

